using FluentAssertions;
using SilverModManager.Games.FromSoft.Cleanup.SaveToLibrary;

namespace SilverModManager.Games.FromSoft.Tests.Cleanup.SaveToLibrary;

public class ProvenanceReaderTests
{
    private const string Lock = """
        # Generated by a mod manager.

        [adjust-the-fov]
        version = "2.0"
        file_id = "5087"
        asset = "AdjustTheFov-325-2-0-1653830963.zip"
        sha256 = "00"
        source = "nexus"

        [questpath]
        version = "1.3.0"
        asset = "QuestPath 10363 1.3.0 2026-07-19T20-46Z NhlU57Tcv.rar"
        sha256 = "11"
        source = "nexus"

        [me3-host]
        version = "v0.13.0"
        asset = "me3-host-v0.13.0.tar.gz"
        sha256 = "22"
        source = "github"
        """;

    [Fact]
    public void ReadsEveryEntryWithItsFileIdWhenThereIsOne()
    {
        var list = ProvenanceReader.Read(Lock);

        list.Problems.Should().BeEmpty();
        list.Entries.Should().Equal(
            new ProvenanceEntry("adjust-the-fov", "nexus", "2.0", 5087, "AdjustTheFov-325-2-0-1653830963.zip"),
            new ProvenanceEntry("questpath", "nexus", "1.3.0", null, "QuestPath 10363 1.3.0 2026-07-19T20-46Z NhlU57Tcv.rar"),
            new ProvenanceEntry("me3-host", "github", "v0.13.0", null, "me3-host-v0.13.0.tar.gz"));
    }

    [Fact]
    public void AGoodEntryBesideJunkIsStillRead()
    {
        var list = ProvenanceReader.Read("""
            top = "not a table"

            [bad-source]
            source = 5

            [no-source]
            version = "1"

            [bad-id]
            source = "nexus"
            file_id = "12; rm -rf /"
            asset = "A-1-1-1652303340.zip"
            version = "1"

            [fine]
            source = "nexus"
            file_id = "7"
            """);

        list.Entries.Select(e => e.Id).Should().Equal("bad-id", "fine");
        list.Entries.Single(e => e.Id == "bad-id").FileId.Should().BeNull();
        list.Entries.Single(e => e.Id == "fine").FileId.Should().Be(7u);
        list.Problems.Should().HaveCount(4);
        list.Problems.Should().Contain(p => p.Contains("top")).And.Contain(p => p.Contains("bad-source")).And.Contain(p => p.Contains("no-source")).And.Contain(p => p.Contains("bad-id"));
    }

    [Theory]
    [InlineData("this is = = not toml [[[")]
    [InlineData("")]
    [InlineData("\0\0\0")]
    public void TextThatIsNotALockGivesNoEntriesAndAReason(string text)
    {
        var list = ProvenanceReader.Read(text);

        list.Entries.Should().BeEmpty();
        if (text.Length > 0) list.Problems.Should().NotBeEmpty();
    }

    [Fact]
    public void AFileOverTheSizeCapIsRefusedWithAReason()
    {
        var list = ProvenanceReader.Read(new string('#', ProvenanceReader.MaxChars + 1));

        list.Entries.Should().BeEmpty();
        list.Problems.Should().ContainSingle().Which.Should().Contain("too large");
    }

    [Fact]
    public void AnAbsurdlyLongValueIsTreatedAsMissing()
    {
        var list = ProvenanceReader.Read($"[a]\nsource = \"nexus\"\nasset = \"{new string('x', 5000)}\"\n");

        list.Entries.Should().ContainSingle().Which.Asset.Should().BeNull();
    }

    [Fact]
    public void FileIdsOutsideTheUnsignedRangeAreIgnored()
    {
        var list = ProvenanceReader.Read("[a]\nsource = \"nexus\"\nfile_id = \"-4\"\n[b]\nsource = \"nexus\"\nfile_id = \"99999999999\"\n");

        list.Entries.Should().OnlyContain(e => e.FileId == null);
    }
}
